import pandas as pd

def drawdown_table(equity, k):
    e = pd.Series(equity, dtype=float)
    day = lambda j: e.index[j].strftime("%Y-%m-%d")
    spells, peak, trough = [], 0, None
    for i in range(1, len(e)):
        if e.iloc[i] >= e.iloc[peak]:
            if trough is not None:
                spells.append((peak, trough, i))      # recovered on day i
            peak, trough = i, None
        elif trough is None or e.iloc[i] < e.iloc[trough]:
            trough = i
    if trough is not None:
        spells.append((peak, trough, None))           # still under water
    rows = [(day(p), day(t), day(r) if r is not None else None,
             round(float(e.iloc[t] / e.iloc[p] - 1), 4)) for p, t, r in spells]
    rows.sort(key=lambda row: row[3])
    return rows[:k]

