def tear_sheet(bars, lookback, cash0=1_000_000, half_spread_bp=2.0, c=1.0, adv=2_000_000, sigma=0.012):
    def costs(q, p):                          # commission and half spread, plus square-root impact
        return (trade_cost(q, p, half_spread_bp=half_spread_bp)
                + abs(q) * p * slippage_bp(q, adv, sigma, c) / 10_000)
    o0, close = bars["open"].iloc[0], bars["close"]
    units = int(cash0 // o0)                  # the shares buy and hold buys
    run = backtest(bars, target_positions(momentum_signal(close, lookback), units), cash0, costs)
    pos = (run["shares"] * close / run["equity"]).shift(1).fillna(0)
    bench = cash0 - units * o0 - costs(units, o0) + units * close
    bpos = (units * close / bench).shift(1).fillna(0)
    return {"strategy": metrics(run["equity"], pos, bench),
            "buy_and_hold": metrics(bench, bpos, bench)}
